codeCorrect:
// Live path: O(n) stride decimation, NO Douglas-Peucker.
function getLivePolyline() as Array {
    var n = _gpsRaw.size();
    if (!_gpsEnabled || n < 2) { return []; }
    if (_liveRawSize == n) { return _liveCache; }
    var cap = Constants.POLYLINE_MAX_SIMPLIFIED;
    var stride = (n + cap - 1) / cap;            // ceil(n/cap)
    if (stride < 1) { stride = 1; }
    var out = [] as Array;
    for (var i = 0; i < n; i += stride) { out.add(_gpsRaw[i]); }
    if ((n - 1) % stride != 0) { out.add(_gpsRaw[n - 1]); }   // keep latest fix
    _liveCache = out; _liveRawSize = n;
    return out;
}
// Full RDP fidelity computed ONCE, off the hot path:
function stopSession() { _gpsSimplified = GeoUtil.simplifyCapped(_gpsRaw, TOL, CAP); }

