hidden var _lockUntilMs = 0;
hidden var _lockActive = false;      // explicit, not inferred from a sentinel

function startPenalty(nowMs) {
    _lockUntilMs = nowMs + Constants.PENALTY_MS;   // may overflow; that is fine
    _lockActive = true;
}

function lockRemainingMs(nowMs) {
    if (!_lockActive) { return 0; }
    var r = _lockUntilMs.toLong() - nowMs.toLong();       // widen: no overflow
    if (r <= 0) { return 0; }
    if (r > Constants.PENALTY_MS) { return 0; }           // wrapped => self-heal
    return r.toNumber();
}

function isLocked(nowMs) {
    if (!_lockActive) { return false; }
    if (lockRemainingMs(nowMs) <= 0) { _lockActive = false; return false; }
    return true;
}

function elapsedSecs(nowMs) {
    var d = nowMs.toLong() - _startedAtMs.toLong();
    if (d < 0) { d = 0; }                                 // wrap => 0, not huge
    return (d / 1000).toNumber();
}

