// Clamp first — null/NaN/negative/over-range never reach setData().
// NaN fails every comparison, so it falls through to 0.
function u(value, maxVal) {
    if (value == null) { return 0; }
    if (value instanceof Toybox.Lang.Number) {
        if (value < 0) { return 0; }
        if (value > maxVal) { return maxVal; }
        return value;
    }
    if (value instanceof Toybox.Lang.Float) {
        if (value >= maxVal) { return maxVal; }
        if (value >= 0) { return value.toNumber(); }
    }
    return 0;
}

